using System.Text.Json;
using Md.Core.Text;

namespace Md.Core.Tests;

/// <summary>
/// MarkdownFormatting against the shared oracle. <c>Fixtures/formatting-vectors.json</c> is the
/// cross-port contract for the formatting commands (docs/formatting.md): 127 <c>format</c> and 10
/// <c>wrapTyped</c> vectors generated by <c>tools/formatting-reference/</c> and copied verbatim into
/// md, md.macOS and md.Android. Every offset is a UTF-16 code unit; <c>expected</c> is the edit to
/// the original text and the selection in the result, or JSON null for no edit. No vector is
/// skipped; a disputed one is changed in the reference first.
/// </summary>
public class MarkdownFormattingTests
{
    public static TheoryData<string> FormatIds() => Ids("format");
    public static TheoryData<string> WrapIds() => Ids("wrapTyped");

    static TheoryData<string> Ids(string section)
    {
        var data = new TheoryData<string>();
        foreach (var vector in Vectors(section)) data.Add(vector.GetProperty("id").GetString()!);
        return data;
    }

    static IEnumerable<JsonElement> Vectors(string section)
    {
        using var document = JsonDocument.Parse(File.ReadAllBytes(Fixtures.Path("formatting-vectors.json")));
        return document.RootElement.GetProperty(section).EnumerateArray().Select(v => v.Clone()).ToList();
    }

    static JsonElement Vector(string section, string id) =>
        Vectors(section).Single(v => v.GetProperty("id").GetString() == id);

    static FormatOp Op(string name) => name switch
    {
        "bold" => FormatOp.Bold,
        "italic" => FormatOp.Italic,
        "code" => FormatOp.Code,
        "strikethrough" => FormatOp.Strikethrough,
        "link" => FormatOp.Link,
        "heading1" => FormatOp.Heading1,
        "heading2" => FormatOp.Heading2,
        "heading3" => FormatOp.Heading3,
        "heading4" => FormatOp.Heading4,
        "heading5" => FormatOp.Heading5,
        "heading6" => FormatOp.Heading6,
        "headingCycle" => FormatOp.HeadingCycle,
        "bulletList" => FormatOp.BulletList,
        "taskList" => FormatOp.TaskList,
        "quote" => FormatOp.Quote,
        "indent" => FormatOp.Indent,
        "outdent" => FormatOp.Outdent,
        _ => throw new ArgumentOutOfRangeException(nameof(name), name, "Unknown op in the vectors"),
    };

    static void AssertEdit(JsonElement expected, FormatEdit? actual, string id)
    {
        if (expected.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{id}: expected no edit, got {actual}");
            return;
        }
        Assert.True(actual is not null, $"{id}: expected an edit, got none");
        var want = new FormatEdit(
            expected.GetProperty("start").GetInt32(),
            expected.GetProperty("end").GetInt32(),
            expected.GetProperty("text").GetString()!,
            expected.GetProperty("selectionStart").GetInt32(),
            expected.GetProperty("selectionEnd").GetInt32());
        Assert.Equal(want, actual!.Value);
    }

    [Fact]
    public void TheOracleIsWhole()
    {
        Assert.Equal(127, Vectors("format").Count());
        Assert.Equal(10, Vectors("wrapTyped").Count());
    }

    [Theory]
    [MemberData(nameof(FormatIds))]
    public void Format(string id)
    {
        var v = Vector("format", id);
        var text = v.GetProperty("text").GetString()!;
        var edit = MarkdownFormatting.Format(text, v.GetProperty("selectionStart").GetInt32(), v.GetProperty("selectionEnd").GetInt32(), Op(v.GetProperty("op").GetString()!));
        AssertEdit(v.GetProperty("expected"), edit, id);
    }

    [Theory]
    [MemberData(nameof(WrapIds))]
    public void WrapTyped(string id)
    {
        var v = Vector("wrapTyped", id);
        var edit = MarkdownFormatting.WrapTyped(
            v.GetProperty("text").GetString()!, v.GetProperty("selectionStart").GetInt32(), v.GetProperty("selectionEnd").GetInt32(), v.GetProperty("typed").GetString()!);
        AssertEdit(v.GetProperty("expected"), edit, id);
    }

    [Fact]
    public void AReversedSelectionIsTheSameSelection()
    {
        Assert.Equal(MarkdownFormatting.Format("say hello", 4, 9, FormatOp.Bold), MarkdownFormatting.Format("say hello", 9, 4, FormatOp.Bold));
        Assert.Equal(MarkdownFormatting.WrapTyped("ab", 0, 2, "*"), MarkdownFormatting.WrapTyped("ab", 2, 0, "*"));
    }

    [Fact]
    public void ApplyToSplicesTheOriginal() =>
        Assert.Equal("say **hello** now", MarkdownFormatting.Format("say hello now", 4, 9, FormatOp.Bold)!.Value.ApplyTo("say hello now"));
}
